import catalog from '../mcp/tool-catalog.json';

// v34 HELP (PLAN G6): what the User Guide's tool reference shows, read from TailorIT's own MCP server. The JSON beside
// the MCP contracts (../mcp/tool-catalog.json) is GENERATED by apps/api/test/mcp-tool-catalog.test.ts from the
// in-process server's tools/list and prompts/list; that test fails while the file and the server differ. Write it again
// with `WRITE_TOOL_CATALOG=1 npx vitest run apps/api/test/mcp-tool-catalog.test.ts` (or `npm run help:tools`) after a
// tool is added, renamed, retitled or re-annotated. The API never imports this module (only the guide and the test).

/** The note at the top of the generated file. */
export const MCP_TOOL_CATALOG_NOTE =
  'GENERATED by apps/api/test/mcp-tool-catalog.test.ts from the MCP server (WRITE_TOOL_CATALOG=1); do not edit by hand.';

/** A tool's MCP annotations, as tools/list answers them (title aside: it is the tool's own field). */
export interface McpCatalogAnnotations {
  readOnlyHint?: boolean;
  destructiveHint?: boolean;
  idempotentHint?: boolean;
  openWorldHint?: boolean;
}

/** One tool of the server. */
export interface McpCatalogTool {
  name: string;
  title: string;
  annotations: McpCatalogAnnotations;
  /** Whether it takes `profile` ("me" or a shared profile's key). */
  profile: boolean;
  /** Its other inputs' names, sorted. */
  inputs: string[];
  /** The sharing box (a SharePermission) it needs on a profile shared with the caller; null: the caller's own only. */
  sharedBox: string | null;
}

/** One MCP prompt of the server (a client may offer it as a command). */
export interface McpCatalogPrompt {
  name: string;
  title: string;
  arguments: string[];
}

export interface McpToolCatalog {
  note: string;
  tools: McpCatalogTool[];
  prompts: McpCatalogPrompt[];
}

/** The server's tools and prompts as the generated file holds them (sorted by name). */
export const MCP_TOOL_CATALOG: McpToolCatalog = catalog as McpToolCatalog;

/** Whether a tool only reads (its readOnlyHint). */
export const toolReadsOnly = (tool: McpCatalogTool): boolean => tool.annotations.readOnlyHint === true;

/** A tool by name, or undefined. */
export function catalogTool(name: string, from: McpToolCatalog = MCP_TOOL_CATALOG): McpCatalogTool | undefined {
  return from.tools.find((tool) => tool.name === name);
}
